import 'package:flutter/foundation.dart';
import 'package:flutter_soloud/flutter_soloud.dart';

import '../../models/emote.dart';

/// The spell, emote and end-of-game sound effects in `assets/sounds/`. Generated by
/// `tool/gen_sfx.py`.
enum SfxSound {
  fireCast('fire_cast'),
  fireExplode('fire_explode'),
  iceCast('ice_cast'),
  iceFreeze('ice_freeze'),
  iceShatter('ice_shatter'),

  /// Buzzes for 0.3 s, then cracks: start it 0.3 s before the bolt hits.
  lightningStrike('lightning_strike'),
  lightningZap('lightning_zap'),
  shieldUp('shield_up'),
  shieldBlock('shield_block'),
  shieldBreak('shield_break'),

  /// Pulse at the start, the hit lands 0.32 s later.
  shieldBash('shield_bash'),
  shieldDouble('shield_double'),
  clashStruggle('clash_struggle'),

  // Emotes
  emoteSend('emote_send'),
  emoteHallo('emote_hallo'),
  emoteHaha('emote_haha'),
  emoteBoos('emote_boos'),
  emoteHuilen('emote_huilen'),
  emoteGg('emote_gg'),
  emoteGoed('emote_goed'),

  // End of a game: "de-de-duuu" and "duh, duh, duuuh". Their note timings
  // are mirrored in the result screen animation.
  resultWin('result_win'),
  resultLose('result_lose');

  const SfxSound(this.file);

  final String file;

  String get asset => 'assets/sounds/$file.wav';

  /// The sound the other player hears when [emote] arrives.
  static SfxSound forEmote(Emote emote) => switch (emote) {
    Emote.hallo => emoteHallo,
    Emote.haha => emoteHaha,
    Emote.boos => emoteBoos,
    Emote.huilen => emoteHuilen,
    Emote.gg => emoteGg,
    Emote.goedGespeeld => emoteGoed,
  };
}

/// Plays the spell and emote sound effects.
///
/// Uses SoLoud because it leaves the phone's audio session alone: the
/// voice chat (WebRTC) keeps its call mode on Android and its session on
/// iOS while effects play on top.
///
/// Does nothing until [init] has finished, and when it fails (tests,
/// platforms without audio), so callers never have to check.
class SfxService {
  SfxService._();

  static final instance = SfxService._();

  /// Off in the settings: [play] stays silent.
  bool enabled = true;

  final _sources = <SfxSound, AudioSource>{};
  Future<void>? _init;

  /// Starts the audio engine and loads every sound. Safe to call twice.
  Future<void> init() => _init ??= _load();

  Future<void> _load() async {
    try {
      final soloud = SoLoud.instance;
      if (!soloud.isInitialized) await soloud.init();
      for (final sound in SfxSound.values) {
        _sources[sound] = await soloud.loadAsset(sound.asset);
      }
    } catch (e) {
      debugPrint('SfxService.init: $e');
    }
  }

  void play(SfxSound sound, {double volume = 1}) {
    if (!enabled) return;
    final source = _sources[sound];
    if (source == null) return;
    try {
      SoLoud.instance.play(source, volume: volume);
    } catch (e) {
      debugPrint('SfxService.play($sound): $e');
    }
  }
}
